import{_ as a,c as r,o,a3 as e}from"./chunks/framework.CoV49S2T.js";const h=JSON.parse('{"title":"カスタマイズ","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/customize.md","filePath":"ja/guide/customize.md","lastUpdated":1787284674000}'),n={name:"ja/guide/customize.md"};function i(l,t,s,d,g,c){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="カスタマイズ" tabindex="-1">カスタマイズ <a class="header-anchor" href="#カスタマイズ" aria-label="Permalink to &quot;カスタマイズ&quot;">​</a></h1><p>ClipboxAI を、お客様の働き方に合わせて使いこなしてください。このガイドでは、調整できる設定を紹介します。</p><h2 id="一般-general" tabindex="-1">一般（General） <a class="header-anchor" href="#一般-general" aria-label="Permalink to &quot;一般（General）&quot;">​</a></h2><p><strong>ClipboxAI → 設定</strong>（または <code>Cmd+,</code> を押す）を開きます。</p><ul><li><strong>Language（言語）</strong>: English、简体中文、繁體中文、日本語。</li><li><strong>Launch at Login（ログイン時の起動）</strong>: ログイン時にアプリを自動的に起動します。</li><li><strong>Appearance（外観）</strong>: Light、Dark、System（macOS に従う）。</li></ul><h2 id="ai-設定-ai-configuration" tabindex="-1">AI 設定（AI Configuration） <a class="header-anchor" href="#ai-設定-ai-configuration" aria-label="Permalink to &quot;AI 設定（AI Configuration）&quot;">​</a></h2><p>クラウド AI は <strong>設定 → AI</strong> で設定します。</p><table tabindex="0"><thead><tr><th>設定</th><th>オプション</th><th>説明</th></tr></thead><tbody><tr><td><strong>Provider（プロバイダー）</strong></td><td>DeepSeek、MiniMax、GLM、Kimi、Mistral、Ollama、OpenAI、Anthropic、Gemini</td><td>呼び出す OpenAI 互換サービス</td></tr><tr><td><strong>API Key</strong></td><td>お客様のキー</td><td><strong>Keychain</strong> に保存され、平文でディスクに書き込まれることはない</td></tr><tr><td><strong>Model（モデル）</strong></td><td>プロバイダーごと</td><td>AI アクションに使用するモデル</td></tr><tr><td><strong>Cloud AI enabled（クラウド AI 有効）</strong></td><td>On / Off</td><td>クリップをクラウドに送信するためのマスタースイッチ</td></tr></tbody></table><p>クラウド AI は<strong>既定でオフ</strong>です。有効にした場合、クリップが送信されるのは自分で設定したプロバイダーだけです。</p><h2 id="アクション-actions" tabindex="-1">アクション（Actions） <a class="header-anchor" href="#アクション-actions" aria-label="Permalink to &quot;アクション（Actions）&quot;">​</a></h2><p>ツールの動作をカスタマイズします。</p><ul><li><strong>Auto-run on output（出力時の自動実行）</strong>: オンの場合、コピーした瞬間に選択したツールが自動的に実行されます。</li><li><strong>Excluded apps（除外アプリ）</strong>: ここに記載されたアプリは、クリップボード監視と自動実行の対象から除外されます（パスワードマネージャーなど）。</li><li><strong>Tool order（ツールの順序）</strong>: AI ツールウィンドウ内で、インストール済みツールをドラッグして並び順を変更でき、その順序は記憶されます。</li></ul><h2 id="プライバシー-privacy" tabindex="-1">プライバシー（Privacy） <a class="header-anchor" href="#プライバシー-privacy" aria-label="Permalink to &quot;プライバシー（Privacy）&quot;">​</a></h2><p><strong>設定 → Privacy</strong> を開きます。</p><ul><li><strong>Cloud AI opt-in（クラウド AI オプトイン）</strong>: プロバイダーへデータを送信するためのマスタースイッチ。</li><li><strong>Excluded apps（除外アプリ）</strong>: 特定のアプリのキャプチャを停止します。</li><li><strong>History controls（履歴の管理）</strong>: デバイス上にクリップをどのくらい保持するかを管理します。</li></ul><p>すべての履歴はローカルに留まります。私たちがクリップをアップロードしたり、アナリティクスを実行したりすることはありません。</p><h2 id="マーケットプレイス-marketplace" tabindex="-1">マーケットプレイス（Marketplace） <a class="header-anchor" href="#マーケットプレイス-marketplace" aria-label="Permalink to &quot;マーケットプレイス（Marketplace）&quot;">​</a></h2><p>インストール済みアクションを管理します。</p><ul><li><strong>Browse（閲覧）</strong>: AI ツールウィンドウまたはサイトから <strong>Marketplace</strong> を開きます。</li><li><strong>Install（インストール）</strong>: アクションの <strong>Install</strong> をクリックすると、ディープリンク経由で追加されます。</li><li><strong>Remove（削除）</strong>: <strong>Installed（インストール済み）</strong> 一覧からアクションをアンインストールします。</li></ul><h2 id="メニューバー-menu-bar" tabindex="-1">メニューバー（Menu Bar） <a class="header-anchor" href="#メニューバー-menu-bar" aria-label="Permalink to &quot;メニューバー（Menu Bar）&quot;">​</a></h2><ul><li><strong>Show in menu bar（メニューバーに表示）</strong>: トレイアイコンを有効/無効にします。</li><li><strong>Quit on close（閉じたときに終了）</strong>: アプリをバックグラウンドで動作させるかどうかを選択します。</li></ul><h2 id="ヒント-tips" tabindex="-1">ヒント（Tips） <a class="header-anchor" href="#ヒント-tips" aria-label="Permalink to &quot;ヒント（Tips）&quot;">​</a></h2><ul><li>必要になるまでクラウド AI はオフにしておきましょう — ローカルツールで日々の整理のほとんどに対応できます。</li><li>パスワードマネージャーやセキュア入力アプリを <strong>Excluded apps（除外アプリ）</strong> に追加し、秘密情報がキャプチャされないようにしましょう。</li><li>自動実行とローカルツールを組み合わせれば、コピーのたびに手を触れずにテキストを整えられます。</li></ul>',23)])])}const p=a(n,[["render",i]]);export{h as __pageData,p as default};
